import { alertModal, callBotModal } from '../modal/ConfirmAlerts';

export const validateIsAuthenticated = (isAuthenticated, isDarkMode) => {
    if (!isAuthenticated) {
      alertModal(isDarkMode, `FURR-SST LOG IN!`);
      return false;
    }
    return true;
  }
  
  export const validateCreatorId = (creator_id, user_id, isDarkMode) => {
    if (creator_id === user_id) {
      alertModal(
        isDarkMode,
        `YOU'VE CAT TO BE KITTEN ME! DIS YOUR OWN GAME!`
      );
      return false;
    }
    return true;
  }

  export const callBot = async (creator_id, room_id, user_id, isDarkMode, updateRoomBot) => {
    if (creator_id === user_id) {
      callBotModal(
        isDarkMode,
        'CALL BOT ON YOUR GAME?',
        'Call',
        'Cancel',
        async () => {
          await updateRoomBot(room_id)
        }
      );
      return false;
    }
    return true;
  }
  
  export const validateBankroll = (bet_amount, bankroll, isDarkMode) => {
    if (bet_amount > bankroll) {
      console.log(bet_amount, bankroll)
      alertModal(
        isDarkMode,
        `BET NOT PAWS-SIBLE, NOT ENOUGH BANKROLL OR GAME HAS FINISHED`);
      return false;
    }
    return true;
  }
  

  export const validateBetAmount = (bet_amount, balance, isDarkMode) => {
    if (isNaN(bet_amount)) {
      alertModal(isDarkMode, 'IM-PAW-SIBBLEEE, ENTER A VALID NUMBER!');
      return false;
    }
  
    if (bet_amount <= 0) {
      alertModal(isDarkMode, `ENTER AN AMOUNT DUMBASS!`);
      return false;
    }

    if (bet_amount < 0.0001) {
      alertModal(isDarkMode, `MEOWNIMUM BET IS 0.0001 SOL`);
      return false;
    }
  
    if (bet_amount > balance) {
      alertModal(isDarkMode, `NOT ENUFF FUNDS AT THIS MEOWMENT`);
      return false;
    }
  
    return true;
  }
  
  export const validateLocalStorageLength = (storageName, isDarkMode) => {
    if (storageName.length < 3) {
      alertModal(isDarkMode, "PURR-HAPS YOU SHOULD BET MANUALLY FOR AT LEAST 3 TURNS TO TRAIN THE AI PLAY");
      return false;
    }
    return true;
  };
  